function chapter(lang) {
  const it = lang === 'it';
  const raw = fs.readFileSync(path.join(ROOT, 'content', it ? 'chapter-one-it.txt' : 'chapter-one-en.txt'), 'utf8').trim();
  const paras = raw.split(/\r?\n\s*\r?\n/).map(p => p.trim()).filter(Boolean);
  const rendered = paras.map((p, i) => `${i === 4 ? `<aside class="reading-note"><span>${it ? 'Continua il caso' : 'Stay with the case'}</span><a href="#newsletter-${lang}">${it ? 'Ricevi gli aggiornamenti del progetto' : 'Get project updates'} →</a></aside>` : ''}<p>${esc(p)}</p>`).join('\n');
  const body = `<div class="reading-progress" aria-hidden="true"><span data-reading-progress></span></div>
    <section class="reading-hero">${image('case-table', it ? 'Un telefono e una cartella del caso su un tavolo scuro' : 'A phone and a case folder on a dark table', 'reading-hero__media', '100vw', 'eager')}<div class="container reading-hero__content"><p class="eyebrow">Daniel Belmont · ${it ? 'Anteprima gratuita' : 'Free preview'}</p><h1>${it ? 'Capitolo Uno' : 'Chapter One'}<br><em>${it ? 'La Porta' : 'The Door'}</em></h1><p>${it ? 'Testo integrale del primo capitolo.' : 'The complete first chapter.'}</p><a class="reading-start" href="#chapter-text">${it ? 'Inizia a leggere' : 'Begin reading'} ↓</a></div></section>
    <article class="chapter-text" id="chapter-text"><header><p class="chapter-kicker">${it ? 'Capitolo Uno' : 'Chapter One'}</p><h2>${it ? 'La Porta' : 'The Door'}</h2><p class="chapter-byline">${it ? 'di' : 'by'} Davide Guerra</p></header>${rendered}</article>
    <section class="chapter-end"><div class="container"><p class="eyebrow">${it ? 'Il caso è appena cominciato' : 'The case has only begun'}</p><h2>${it ? 'Che cosa significa quella porta aperta?' : 'What does the open door mean?'}</h2><p>${it ? 'Segui lo sviluppo di Daniel Belmont e la campagna Kickstarter, oppure ricevi soltanto gli aggiornamenti che contano.' : 'Follow the development of Daniel Belmont and the Kickstarter campaign, or receive only the updates that matter.'}</p><div class="button-row"><a class="button button--light" href="${it ? KICKSTARTER_IT : KICKSTARTER_EN}" target="_blank" rel="noopener">Kickstarter ↗</a><a class="button button--ghost" href="${routes.daniel[lang]}">${it ? 'Esplora il progetto' : 'Explore the project'}</a></div></div></section>${newsletter(lang, true)}`;
  return layout({lang, page:'chapter', title: it ? 'Capitolo Uno — La Porta | Daniel Belmont' : 'Chapter One — The Door | Daniel Belmont', description: it ? 'Leggi integralmente il Capitolo Uno di Daniel Belmont — Il giorno in cui nessuno ha chiamato.' : 'Read the complete first chapter of Daniel Belmont — The Day No One Called.', og:'og-chapter-one.webp', article:true, body});
}

