function about(lang) {
  const it = lang === 'it';
  const body = `${pageHero(it ? 'L’autore' : 'About', 'Davide Guerra', it ? 'Scrive storie, raccoglie frammenti e sviluppa progetti a partire dalle cose che meritano una seconda occhiata.' : 'He writes stories, collects fragments and develops projects from the things that deserve a second look.')}
    <section class="section"><div class="container about-grid"><div class="about-monogram" aria-hidden="true">DG</div><div class="prose prose--large"><p>${it ? 'Davide Guerra è nato a Foggia il 25 luglio 2004. Lavora come tecnico di manutenzione, un mestiere fatto di attenzione, metodo e problemi concreti da risolvere.' : 'Davide Guerra was born in Foggia, Italy, on 25 July 2004. He works as a maintenance technician—a job grounded in attention, method and concrete problems to solve.'}</p><p>${it ? 'La scrittura nasce nello spazio tra una giornata e l’altra. Il suo primo libro pubblicato, L’Arte della Solitudine, raccoglie frammenti, pensieri e meditazioni. Il progetto attuale, Daniel Belmont — Il giorno in cui nessuno ha chiamato, porta la stessa attenzione per i dettagli dentro un’indagine.' : 'Writing happens in the space around the working day. His first published book, The Art of Solitude, gathers fragments, thoughts and meditations. His current project, Daniel Belmont — The Day No One Called, brings that same attention to detail into an investigation.'}</p><p>${it ? 'Accanto ai libri sviluppa idee digitali e progetti personali. Non li presenta come promesse: li documenta quando esiste qualcosa di reale da condividere.' : 'Alongside books, he develops digital ideas and personal projects. They are not presented as promises; they are documented when there is something real to share.'}</p><div class="button-row"><a class="button" href="${routes.chapter[lang]}">${it ? 'Leggi il Capitolo Uno' : 'Read Chapter One'}</a><a class="text-link" href="${INSTAGRAM}" target="_blank" rel="noopener">Instagram ↗</a></div></div></div></section>
    <section class="section section--paper-deep"><div class="container values-grid"><div><span>01</span><h2>${it ? 'Osservare' : 'Observe'}</h2><p>${it ? 'Prima di spiegare, guardare meglio.' : 'Look more closely before explaining.'}</p></div><div><span>02</span><h2>${it ? 'Ridurre' : 'Reduce'}</h2><p>${it ? 'Lasciare soltanto ciò che ha peso.' : 'Keep only what carries weight.'}</p></div><div><span>03</span><h2>${it ? 'Costruire' : 'Build'}</h2><p>${it ? 'Trasformare un’intuizione in una forma utile.' : 'Turn an intuition into a useful form.'}</p></div></div></section>${newsletter(lang, true)}`;
  return layout({lang, page:'about', title: it ? 'Davide Guerra — Autore' : 'Davide Guerra — Author', description: it ? 'Biografia di Davide Guerra, autore de L’Arte della Solitudine e del nuovo thriller Daniel Belmont.' : 'About Davide Guerra, author of The Art of Solitude and the new Daniel Belmont thriller.', body});
}

