function messagePage(lang, kind) {
  const it = lang === 'it';
  const isCheck = kind === 'check';
  const title = isCheck ? (it ? 'Controlla la tua email' : 'Check your email') : (it ? 'Iscrizione confermata' : 'Subscription confirmed');
  const text = isCheck ? (it ? 'Ti abbiamo inviato un messaggio di conferma. Controlla anche le cartelle Spam e Promozioni e apri il link per completare l’iscrizione.' : 'A confirmation message has been sent. Check Spam and Promotions too, then open the link to complete your subscription.') : (it ? 'Grazie. Il tuo indirizzo è stato confermato e riceverai soltanto gli aggiornamenti che contano.' : 'Thank you. Your address is confirmed, and you will receive only the updates that matter.');
  const body = `<section class="message-page"><div class="container"><span class="message-page__mark">${isCheck ? '✉' : '✓'}</span><p class="eyebrow">Newsletter</p><h1>${title}</h1><p>${text}</p><a class="button button--light" href="${routes.home[lang]}">${it ? 'Torna alla pagina iniziale' : 'Return home'}</a></div></section>`;
  return layout({lang, page:kind, title:`${title} — Davide Guerra`, description:text, body});
}

function writeRoute(route, html) {
  if (route === '/') return fs.writeFileSync(path.join(ROOT, 'index.html'), html);
  const dir = path.join(ROOT, route.replace(/^\//, '').replace(/\/$/, ''));
  fs.mkdirSync(dir, {recursive:true});
  fs.writeFileSync(path.join(dir, 'index.html'), html);
}

const generators = {home, daniel, chapter, books, projects, updates, about, contact, privacy};
for (const [page, make] of Object.entries(generators)) {
  writeRoute(routes[page].en, make('en'));
  writeRoute(routes[page].it, make('it'));
}
writeRoute(routes.check.en, messagePage('en', 'check'));
writeRoute(routes.check.it, messagePage('it', 'check'));
writeRoute(routes.confirmed.en, messagePage('en', 'confirmed'));
writeRoute(routes.confirmed.it, messagePage('it', 'confirmed'));

function redirect(target, lang = 'en') {
  return `<!doctype html><html lang="${lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta http-equiv="refresh" content="0; url=${target}"><link rel="canonical" href="${BASE}${target}"><title>Redirecting…</title><script>location.replace('${target}')</script></head><body><p><a href="${target}">Continue</a></p></body></html>`;
}

const aliases = {
  '/en/':'/', '/en/books/':'/books/', '/en/projects/':'/projects/', '/en/updates/':'/updates/', '/en/author/':'/about/', '/en/contact/':'/contact/', '/en/privacy/':'/privacy/', '/en/kickstarter/':'/daniel-belmont/', '/en/journal/daniel-belmont/':'/daniel-belmont/', '/en/reviews/':'/books/#reviews',
  '/en/journal/art-of-solitude/':'/books/', '/en/newsletter/check-email/':'/newsletter/check-email/', '/en/newsletter/confirmed/':'/newsletter/confirmed/',
  '/autore/':'/it/autore/', '/opere/':'/it/libri/', '/progetti/':'/it/progetti/', '/aggiornamenti/':'/it/aggiornamenti/', '/contatti/':'/it/contatti/', '/recensioni/':'/it/libri/#recensioni', '/diario/daniel-belmont/':'/it/daniel-belmont/', '/diario/arte-della-solitudine/':'/it/libri/', '/kickstarter/':'/daniel-belmont/', '/newsletter/controlla-email/':'/it/newsletter/controlla-email/', '/newsletter/confermata/':'/it/newsletter/confermata/'
};
for (const [from, to] of Object.entries(aliases)) writeRoute(from, redirect(to, from.startsWith('/en/') ? 'en' : 'it'));

const fileAliases = {
  'chi-sono.html':'/it/autore/', 'libri.html':'/it/libri/', 'progetti.html':'/it/progetti/', 'aggiornamenti.html':'/it/aggiornamenti/', 'contatti.html':'/it/contatti/', 'privacy.html':'/it/privacy/', 'kickstarter.html':'/daniel-belmont/', 'recensioni.html':'/it/libri/#recensioni', 'diario-daniel-belmont.html':'/it/daniel-belmont/', 'diario-arte-della-solitudine.html':'/it/libri/', 'newsletter-check-email.html':'/it/newsletter/controlla-email/', 'newsletter-confirmed.html':'/it/newsletter/confermata/',
  'en/chi-sono.html':'/about/', 'en/libri.html':'/books/', 'en/progetti.html':'/projects/', 'en/aggiornamenti.html':'/updates/', 'en/contatti.html':'/contact/', 'en/privacy.html':'/privacy/', 'en/kickstarter.html':'/daniel-belmont/', 'en/recensioni.html':'/books/#reviews', 'en/diario-daniel-belmont.html':'/daniel-belmont/', 'en/diario-arte-della-solitudine.html':'/books/', 'en/newsletter-check-email.html':'/newsletter/check-email/', 'en/newsletter-confirmed.html':'/newsletter/confirmed/'
};
for (const [file, to] of Object.entries(fileAliases)) fs.writeFileSync(path.join(ROOT, file), redirect(to, file.startsWith('en/') ? 'en' : 'it'));

const sitemapRoutes = Object.values(routes).flatMap(pair => [pair.en, pair.it]);
fs.writeFileSync(path.join(ROOT, 'sitemap.xml'), `<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n${sitemapRoutes.map(r => `  <url><loc>${BASE}${r}</loc><lastmod>2026-09-23</lastmod></url>`).join('\n')}\n</urlset>\n`);
fs.writeFileSync(path.join(ROOT, 'robots.txt'), `User-agent: *\nAllow: /\n\nSitemap: ${BASE}/sitemap.xml\n`);
fs.writeFileSync(path.join(ROOT, 'README.md'), `# Davide Guerra website\n\nBilingual static website. English is the default language at the root; Italian lives under \`/it/\`.\n\n## Build\n\nRun \`node build-site.js\` from this folder. The build writes the canonical page directories and the legacy redirects.\n\n## Content rules\n\nOnly Chapter One of Daniel Belmont is published. Chapters Two–Seven are private continuity material and are not included in the site output. Newsletter forms use the existing Brevo endpoints and double opt-in fields.\n`);

console.log(`Built ${sitemapRoutes.length} canonical pages and ${Object.keys(aliases).length + Object.keys(fileAliases).length} redirects.`);
